#!/usr/bin/env bash
# Start the web demo with this project's isolated Python environment.
set -euo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
ROOT="$(cd "$HERE/.." && pwd)"
PYTHON="$ROOT/.venv/bin/python"
if [[ ! -x "$PYTHON" ]]; then
    echo "Missing project environment. Run: python3 -m venv $ROOT/.venv" >&2
    echo "Then install requirements with $ROOT/.venv/bin/python -m pip install -r $ROOT/requirements.txt" >&2
    exit 1
fi
# Keep generated bytecode outside the signed, immutable SDK payload.
export PYTHONDONTWRITEBYTECODE=1
exec "$PYTHON" -u "$HERE/demo_server.py" "$@"
